pub mod config {
    pub struct Config {
        pub retries: u32,
    }

    pub fn parse(s: &str) -> Config {
        Config { retries: digits(s) }
    }

    fn digits(s: &str) -> u32 {
        s.chars().filter(|c| c.is_ascii_digit()).count() as u32
    }
}

